Ladies and gentlemen, our test suite begins with a joke: the payment always succeeds in staging. Unfortunately, we're all in this together.

```typescript
// Checkout.test.tsx
import { render, screen, waitFor } from '@testing-library/react';
import userEvent from '@testing-library/user-event';
import { describe, it, expect, vi, beforeEach } from 'vitest';
import { axe, toHaveNoViolations } from 'jest-axe';
import { Checkout } from './Checkout';

expect.extend(toHaveNoViolations);

// Mock contexts - the bureaucracy says we need these
const mockProcessPayment = vi.fn();
const mockClearCart = vi.fn();
const mockItems = [
  { id: '1', name: 'Martini Glass', price: 29.99 },
  { id: '2', name: 'Still (Medical)', price: 499.99 }
];

vi.mock('./CartContext', () => ({
  useCart: () => ({ items: mockItems, total: 529.98, clearCart: mockClearCart })
}));

vi.mock('./PaymentContext', () => ({
  usePayment: () => ({ processPayment: mockProcessPayment })
}));

const validShipping = {
  street: '4077 MASH Unit',
  city: 'Uijeongbu',
  state: 'CA',
  zip: '90210'
};

const validPayment = {
  cardNumber: '4111111111111111',
  expiry: '12/25',
  cvv: '123',
  nameOnCard: 'Benjamin Franklin Pierce'
};

describe('Checkout Component', () => {
  beforeEach(() => {
    vi.clearAllMocks();
    mockProcessPayment.mockResolvedValue({ orderId: 'ORD-4077' });
  });

  // HAPPY PATH - complete checkout flow
  it('completes full checkout flow successfully', async () => {
    const user = userEvent.setup();
    const onComplete = vi.fn();
    render(<Checkout onComplete={onComplete} />);

    // Shipping step
    await user.type(screen.getByLabelText(/street/i), validShipping.street);
    await user.type(screen.getByLabelText(/city/i), validShipping.city);
    await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
    await user.type(screen.getByLabelText(/zip/i), validShipping.zip);
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    // Payment step
    await user.type(screen.getByLabelText(/card number/i), validPayment.cardNumber);
    await user.type(screen.getByLabelText(/expiry/i), validPayment.expiry);
    await user.type(screen.getByLabelText(/cvv/i), validPayment.cvv);
    await user.type(screen.getByLabelText(/name on card/i), validPayment.nameOnCard);
    await user.click(screen.getByRole('button', { name: /review order/i }));

    // Review step
    expect(screen.getByText(/martini glass/i)).toBeInTheDocument();
    await user.click(screen.getByRole('button', { name: /place order/i }));

    // Confirmation
    await waitFor(() => {
      expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
    });
    expect(onComplete).toHaveBeenCalledWith('ORD-4077');
  });

  // VALIDATION - shipping form
  it('displays shipping validation errors for empty fields', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/street address is required/i)).toBeInTheDocument();
    expect(screen.getByText(/city is required/i)).toBeInTheDocument();
    expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
  });

  it('validates ZIP code format', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    await user.type(screen.getByLabelText(/zip/i), 'invalid');
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByText(/valid zip code required/i)).toBeInTheDocument();
  });

  // VALIDATION - payment form
  it('displays payment validation errors for invalid card details', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    // Navigate to payment
    await user.type(screen.getByLabelText(/street/i), validShipping.street);
    await user.type(screen.getByLabelText(/city/i), validShipping.city);
    await user.selectOptions(screen.getByLabelText(/state/i), validShipping.state);
    await user.type(screen.getByLabelText(/zip/i), validShipping.zip);
    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    await user.type(screen.getByLabelText(/card number/i), '1234');
    await user.type(screen.getByLabelText(/expiry/i), '13/99');
    await user.click(screen.getByRole('button', { name: /review order/i }));

    expect(screen.getByText(/valid 16-digit card number required/i)).toBeInTheDocument();
    expect(screen.getByText(/valid expiry/i)).toBeInTheDocument();
  });

  // ERROR STATES
  it('displays payment error and allows retry', async () => {
    mockProcessPayment.mockRejectedValueOnce(new Error('Card declined'));
    const user = userEvent.setup();
    render(<Checkout />);

    // Navigate through to review (abbreviated)
    await fillShippingForm(user);
    await fillPaymentForm(user);

    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByRole('alert')).toHaveTextContent(/card declined/i);
    });

    // Retry succeeds
    mockProcessPayment.mockResolvedValueOnce({ orderId: 'ORD-RETRY' });
    await user.click(screen.getByRole('button', { name: /place order/i }));

    await waitFor(() => {
      expect(screen.getByText(/order confirmed/i)).toBeInTheDocument();
    });
  });

  // LOADING STATES
  it('disables buttons and shows loading state during submission', async () => {
    mockProcessPayment.mockImplementation(() => new Promise(() => {})); // Never resolves
    const user = userEvent.setup();
    render(<Checkout />);

    await fillShippingForm(user);
    await fillPaymentForm(user);

    await user.click(screen.getByRole('button', { name: /place order/i }));

    expect(screen.getByRole('button', { name: /processing/i })).toBeDisabled();
    expect(screen.getByRole('button', { name: /back/i })).toBeDisabled();
  });

  // EDGE CASES
  it('displays empty cart message when no items', () => {
    vi.mocked(require('./CartContext').useCart).mockReturnValue({
      items: [], total: 0, clearCart: mockClearCart
    });

    render(<Checkout onCancel={vi.fn()} />);

    expect(screen.getByRole('alert')).toHaveTextContent(/cart is empty/i);
  });

  // ACCESSIBILITY
  it('has no accessibility violations', async () => {
    const { container } = render(<Checkout />);
    const results = await axe(container);
    expect(results).toHaveNoViolations();
  });

  it('marks invalid fields with aria-invalid', async () => {
    const user = userEvent.setup();
    render(<Checkout />);

    await user.click(screen.getByRole('button', { name: /continue to payment/i }));

    expect(screen.getByLabelText(/street/i)).toHaveAttribute('aria-invalid', 'true');
  });
});

// Helper functions - because even surgeons need nurses
async function fillShippingForm(user) {
  await user.type(screen.getByLabelText(/street/i), '4077 MASH');
  await user.type(screen.getByLabelText(/city/i), 'Uijeongbu');
  await user.selectOptions(screen.getByLabelText(/state/i), 'CA');
  await user.type(screen.getByLabelText(/zip/i), '90210');
  await user.click(screen.getByRole('button', { name: /continue to payment/i }));
}

async function fillPaymentForm(user) {
  await user.type(screen.getByLabelText(/card number/i), '4111111111111111');
  await user.type(screen.getByLabelText(/expiry/i), '12/25');
  await user.type(screen.getByLabelText(/cvv/i), '123');
  await user.type(screen.getByLabelText(/name on card/i), 'Hawkeye Pierce');
  await user.click(screen.getByRole('button', { name: /review order/i }));
}
